package com.cinenest.notifications.internal;
import com.cinenest.notifications.NotificationFacts.Fact;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
@Repository
class JdbcNotificationRepository implements NotificationRepository {
 private final JdbcClient jdbc;JdbcNotificationRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 private JdbcClient.StatementSpec sql(String s,Object... p){return jdbc.sql(s).params(p);}
 public void event(Fact f){
  int n=sql("INSERT INTO cinenest_notifications.notification_event(event_id,source,resource_id,source_revision,owner_id,venue_id,kind,reviewers) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",f.event(),f.source(),f.resource(),f.revision(),f.owner(),f.venue(),f.kind().name(),f.reviewers()).update();
  var r=event(f.event());if(!Objects.equals(r.get("source"),f.source())||!Objects.equals(r.get("resource_id"),f.resource())||((Number)r.get("source_revision")).longValue()!=f.revision()||!Objects.equals(r.get("owner_id"),f.owner())||!Objects.equals(r.get("venue_id"),f.venue())||!Objects.equals(r.get("kind"),f.kind().name())||!Objects.equals(r.get("reviewers"),f.reviewers()))throw new NotificationFailure(409);
  if(n>0){sql("INSERT INTO cinenest_notifications.notification_work(operation_id,event_id,state) VALUES(?,?,'UNASSIGNED')",UUID.randomUUID(),f.event()).update();audit(null,f.event(),null,f.venue(),"EVENT_OBSERVED","INTENT_PENDING");}
 }
 public Map<String,Object> event(UUID id){return sql("SELECT * FROM cinenest_notifications.notification_event WHERE event_id=?",id).query().singleRow();}
 public List<Map<String,Object>> unresolved(){return sql("SELECT e.* FROM cinenest_notifications.notification_event e JOIN cinenest_notifications.notification_work w USING(event_id) WHERE w.intent_id IS NULL AND w.state='UNASSIGNED' ORDER BY e.observed_at,e.event_id LIMIT 100 FOR UPDATE OF w SKIP LOCKED").query().listOfRows();}
 public List<Map<String,Object>> unassigned(UUID venue){return sql("SELECT e.event_id,e.kind,e.source,e.resource_id,w.state FROM cinenest_notifications.notification_event e JOIN cinenest_notifications.notification_work w USING(event_id) WHERE e.venue_id=? AND w.intent_id IS NULL AND w.state='UNASSIGNED' ORDER BY e.observed_at,e.event_id LIMIT 100",venue).query().listOfRows();}
 public void intent(UUID event,UUID recipient,boolean staff,int expiry,int retention){var e=event(event);UUID id=UUID.randomUUID();int inserted=sql("INSERT INTO cinenest_notifications.notification_intent(intent_id,event_id,recipient_id,venue_id,source_owner_id,audience,channel,template_version,destination,expires_at,retain_until) VALUES(?,?,?,?,?,?,'IN_APP_SYNTHETIC',1,?,?::timestamptz+?*INTERVAL '1 second',?::timestamptz+?*INTERVAL '1 second') ON CONFLICT DO NOTHING",id,event,recipient,e.get("venue_id"),e.get("owner_id"),staff?"STAFF":"OWNER",e.get("source").equals("PAYMENTS")?"/bank":"/access",e.get("observed_at"),expiry,e.get("observed_at"),retention).update();if(inserted>0)sql("INSERT INTO cinenest_notifications.notification_work(operation_id,event_id,intent_id,state) VALUES(?,?,?,'READY')",UUID.randomUUID(),event,id).update();}
 public void resolved(UUID event){sql("UPDATE cinenest_notifications.notification_work SET state='SUPPRESSED' WHERE event_id=? AND intent_id IS NULL",event).update();}
 private static final String JOIN="SELECT i.*, e.source,e.resource_id,e.source_revision,e.kind,w.operation_id,w.state,w.fixture,w.attempts,w.fence FROM cinenest_notifications.notification_intent i JOIN cinenest_notifications.notification_event e USING(event_id) JOIN cinenest_notifications.notification_work w USING(intent_id) ";
 public List<Map<String,Object>> inbox(UUID actor){return sql(JOIN+"WHERE i.recipient_id=? AND i.available_at IS NOT NULL AND i.expires_at>clock_timestamp() AND i.retain_until>clock_timestamp() ORDER BY i.intent_id",actor).query().listOfRows();}
 public List<Map<String,Object>> queue(UUID venue){return sql(JOIN+"WHERE i.venue_id=? ORDER BY i.intent_id",venue).query().listOfRows();}
 public Map<String,Object> row(UUID id,boolean lock){var rows=sql(JOIN+"WHERE i.intent_id=?"+(lock?" FOR UPDATE OF i,w":""),id).query().listOfRows();if(rows.isEmpty())throw new NotificationFailure(404);return rows.getFirst();}
 public void lockActor(UUID actor){sql("SELECT pg_advisory_xact_lock(hashtextextended(?,14))",actor.toString()).query().singleRow();}
 public long rate(UUID actor,int seconds){return sql("SELECT count(*) FROM cinenest_notifications.notification_audit WHERE actor_id=? AND created_at>clock_timestamp()-?*INTERVAL '1 second'",actor,seconds).query(Long.class).single();}
 public void audit(UUID actor,UUID event,UUID intent,UUID venue,String action,String outcome){sql("INSERT INTO cinenest_notifications.notification_audit(audit_id,actor_id,event_id,intent_id,venue_id,action,outcome) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID(),actor,event,intent,venue,action,outcome).update();}
 public Map<String,Object> command(UUID actor,UUID key){var r=sql("SELECT * FROM cinenest_notifications.notification_command WHERE actor_id=? AND command_key=?",actor,key).query().listOfRows();return r.isEmpty()?Map.of():r.getFirst();}
 public void command(UUID actor,UUID key,UUID intent,String kind,String hash){sql("INSERT INTO cinenest_notifications.notification_command(actor_id,command_key,intent_id,kind,payload_hash) VALUES(?,?,?,?,?)",actor,key,intent,kind,hash).update();}
 public void read(UUID intent){sql("UPDATE cinenest_notifications.notification_intent SET read_at=COALESCE(read_at,clock_timestamp()),revision=revision+1 WHERE intent_id=?",intent).update();}
 public void fixture(UUID intent,String fixture){sql("UPDATE cinenest_notifications.notification_work SET fixture=? WHERE intent_id=?",fixture,intent).update();sql("UPDATE cinenest_notifications.notification_intent SET revision=revision+1 WHERE intent_id=?",intent).update();}
 public void retry(UUID intent,int delay){sql("UPDATE cinenest_notifications.notification_work SET state='READY',due_at=clock_timestamp()+?*INTERVAL '1 second' WHERE intent_id=? AND state='DELIVERY_FAILED'",delay,intent).update();sql("UPDATE cinenest_notifications.notification_intent SET revision=revision+1 WHERE intent_id=?",intent).update();}
 public void reconcile(UUID intent){var r=row(intent,true);UUID operation=(UUID)r.get("operation_id");var evidence=sql("SELECT capture_evidence FROM cinenest_notifications.notification_attempt WHERE operation_id=? AND outcome='DELIVERY_UNKNOWN' AND capture_evidence IS NOT NULL ORDER BY created_at DESC LIMIT 1",operation).query(String.class).list();if(evidence.isEmpty())throw new NotificationFailure(409);boolean accepted=evidence.getFirst().equals("ACCEPTED");sql("UPDATE cinenest_notifications.notification_work SET state=? WHERE operation_id=?",accepted?"SIMULATOR_ACCEPTED":"DELIVERY_FAILED",operation).update();sql("INSERT INTO cinenest_notifications.notification_attempt(attempt_id,operation_id,fence,outcome,capture_evidence) VALUES(?,?,?,?,?)",UUID.randomUUID(),operation,r.get("fence"),accepted?"RECONCILED_ACCEPTED":"RECONCILED_FAILED",evidence.getFirst()).update();sql("UPDATE cinenest_notifications.notification_intent SET available_at=CASE WHEN ? THEN clock_timestamp() ELSE available_at END,revision=revision+1 WHERE intent_id=?",accepted,intent).update();}
 public List<UUID> pending(){return sql("SELECT operation_id FROM cinenest_notifications.notification_work WHERE (state='READY' AND due_at<=clock_timestamp()) OR (state='LEASED' AND lease_until<clock_timestamp()) ORDER BY due_at LIMIT 100").query(UUID.class).list();}
 public Map<String,Object> claim(UUID op,int lease,int limit){var r=sql("SELECT * FROM cinenest_notifications.notification_work WHERE operation_id=? FOR UPDATE SKIP LOCKED",op).query().listOfRows();if(r.isEmpty())return Map.of();var w=r.getFirst();if(w.get("state").equals("LEASED")){int expired=sql("UPDATE cinenest_notifications.notification_work SET state='DELIVERY_UNKNOWN' WHERE operation_id=? AND lease_until<clock_timestamp()",op).update();if(expired>0)sql("INSERT INTO cinenest_notifications.notification_attempt(attempt_id,operation_id,fence,outcome) VALUES(?,?,?,'DELIVERY_UNKNOWN') ON CONFLICT DO NOTHING",UUID.randomUUID(),op,w.get("fence")).update();return Map.of();}if(!w.get("state").equals("READY")||((Number)w.get("attempts")).intValue()>=limit)return Map.of();int claimed=sql("UPDATE cinenest_notifications.notification_work SET state='LEASED',lease_until=clock_timestamp()+?*INTERVAL '1 second',attempts=attempts+1,fence=fence+1 WHERE operation_id=? AND due_at<=clock_timestamp()",lease,op).update();if(claimed==0)return Map.of();long fence=((Number)w.get("fence")).longValue()+1;sql("INSERT INTO cinenest_notifications.notification_attempt(attempt_id,operation_id,fence,outcome) VALUES(?,?,?,'DELIVERY_ATTEMPTED')",UUID.randomUUID(),op,fence).update();return row((UUID)w.get("intent_id"),false);}
 public boolean finish(UUID op,long fence,String outcome,String evidence){int n=sql("UPDATE cinenest_notifications.notification_work SET state=?,lease_until=NULL WHERE operation_id=? AND fence=? AND state='LEASED' AND lease_until>clock_timestamp()",outcome,op,fence).update();if(n==0)return false;sql("INSERT INTO cinenest_notifications.notification_attempt(attempt_id,operation_id,fence,outcome,capture_evidence) VALUES(?,?,?,?,?)",UUID.randomUUID(),op,fence,outcome,evidence).update();sql("UPDATE cinenest_notifications.notification_intent SET available_at=CASE WHEN ?='SIMULATOR_ACCEPTED' THEN clock_timestamp() ELSE available_at END,revision=revision+1 WHERE intent_id=(SELECT intent_id FROM cinenest_notifications.notification_work WHERE operation_id=?)",outcome,op).update();return true;}
 public void suppress(UUID id){sql("UPDATE cinenest_notifications.notification_work SET state='SUPPRESSED',lease_until=NULL WHERE intent_id=?",id).update();sql("UPDATE cinenest_notifications.notification_intent SET available_at=NULL,read_at=NULL,revision=revision+1 WHERE intent_id=?",id).update();}
 public boolean unexpired(UUID id){return sql("SELECT expires_at>clock_timestamp() AND retain_until>clock_timestamp() FROM cinenest_notifications.notification_intent WHERE intent_id=?",id).query(Boolean.class).single();}
 public List<Map<String,Object>> attempts(UUID op){return sql("SELECT attempt_id,fence,outcome,created_at FROM cinenest_notifications.notification_attempt WHERE operation_id=? ORDER BY created_at,attempt_id",op).query().listOfRows();}
 public List<Map<String,Object>> history(UUID id){return sql("SELECT audit_id,action,outcome,created_at FROM cinenest_notifications.notification_audit WHERE intent_id=? ORDER BY created_at,audit_id",id).query().listOfRows();}
}
